import Foundation

/// Pre-bundled Mozilla Readability engine (readability.min.js) compiled into memory
/// to ensure zero runtime file lookup failures across all Apple platforms and test targets.
public enum ReadabilityScript {
    private static let base64Payload = ""
    
    public static let js: String = {
        if let data = Data(base64Encoded: base64Payload),
           let str = String(data: data, encoding: .utf8) {
            return str
        }
        return ""
    }()
}
